{"path":"lib/app/currency_list/currency_list_page.dart","content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  static const int _pageSize = 20;
  var _currentPage = 0;
  bool _hasMore = true;
  var _isLoadingMore = false;
  String? _currentSearchQuery;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  @override
  void initState() {
    _filteredCurrenciesNotifier = ValueNotifier([]);
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      if (mounted) setState(() => _filteredCurrenciesNotifier.value = value);

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(value);
      _hasMore = page.hasMore;
      _currentPage = page.page;

      return value;
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    if (query.trim().isEmpty) {
      _currentSearchQuery = null;
      setState(() => _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies));
      return;
    }

    _currentSearchQuery = query.trim();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    setState(() => _filteredCurrenciesNotifier.value = result.toList(growable: false));
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;
    setState(() => _isLoadingMore = true);
    try {
      final currencyRepository = context.read<CurrencyRepository>();
      final nextPage = _currentPage + 1;
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: _pageSize));

      if (page.items.isEmpty) {
        setState(() => _hasMore = false);
        return;
      }

      final previousCount = _allCurrencies.length;
      _allCurrencies.addAll(page.items);
      _currentPage = nextPage;
      _hasMore = page.hasMore;

      // Apply current search filter if any
      if (_currentSearchQuery != null && _currentSearchQuery!.isNotEmpty) {
        final query = _currentSearchQuery!;
        setState(() => _filteredCurrenciesNotifier.value = _allCurrencies.where((c) => c.name.toLowerCase().contains(query) || c.symbol.toLowerCase().contains(query)).toList(growable: false));
      } else {
        if (mounted) {
          setState(() => _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies));
        }
      }

      // Scroll to the first new item after animation settles
      Future.microtask(() {
        final listViewState = context.findAncestorStateOfType<ListViewBaseState>();
        if (listViewState is StateSetter) return; // not a setter, skip
      });
    } catch (_) {
      // leave current state as-is
    } finally {
      setState(() => _isLoadingMore = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> list, _) {
                      return ListView.builder(
                        itemCount: _hasMore ? list.length + 1 : list.length,
                        itemBuilder: (BuildContext context, int index) {
                          // Show loading / load-more button after the last currency item
                          if (_hasMore && index == list.length) {
                            return Center(
                              child: Padding(
                                padding: const EdgeInsets.symmetric(vertical: 20),
                                child: _isLoadingMore
                                    ? SizedBox(width: 36, height: 36, child: CircularProgressIndicator(strokeWidth: 3))
                                    : FilledButton(
                                        onPressed: _loadMore,
                                        child: Text(context.loc.showMore),
                                      ),
                              ),
                            );
                          }

                          final CurrencyModel currency = list[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: EdgeInsets.fromLTRB(22, 0, 22, _hasMore ? 16 : 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
"}

